请对以下 case 进行三维加权评分。

=== case_id ===
Case-10-rainy-taxi-018

=== 用户原始指令 (query.txt) ===
卡片主视觉雨滴图标,旁边显示"当前雨量:中雨 12mm/h"动态数据。左右分区:左边信息区温度湿度,右边"查看详细"跳天气应用。风速超6级标红"危险:不建议骑行"告警,纯文字色块。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "卡片主视觉雨滴图标,旁边显示\"当前雨量:中雨 12mm/h\"动态数据。左右分区:左边信息区温度湿度,右边\"查看详细\"跳天气应用。风速超6级标红\"危险:不建议骑行\"告警,纯文字色块。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县或当前位置名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "rainCondition": {
            "type": "string",
            "description": "当前降雨等级文本。",
            "sampleValue": "中雨"
          },
          "rainfallRateText": {
            "type": "string",
            "description": "当前小时雨量展示文本。",
            "sampleValue": "12mm/h"
          },
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "24°C"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 88
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级，超过6级时触发危险骑行告警。",
            "sampleValue": 7
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/drop_1.svg",
      "description": "水滴图标，黑色水滴轮廓，适合表达当前降雨量或雨天状态。"
    }
  ]
}

